using System.Collections.Generic;

public class ScannerFiles
{
    public static void ScanAllDrives(string searchText)
    {
        foreach (var drive in DriveInfo.GetDrives())
        {
            try
            {
                if (drive.IsReady)
                {
                    Console.WriteLine($"Scanning drive {drive.Name}");
                    ScanDirectory(drive.RootDirectory.FullName, searchText);
                }
            }
            catch (UnauthorizedAccessException ex)
            {
                Console.WriteLine($"Access denied to drive {drive.Name}: {ex.Message}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error scanning drive {drive.Name}: {ex.Message}");
            }
        }
    }

    private static void ScanDirectory(string path, string searchText)
    {
        try
        {
            var fileEntries = Directory.GetFiles(path);
            foreach (var fileName in fileEntries)
            {
                ScanFile(fileName, searchText);
            }

            var subdirectoryEntries = Directory.GetDirectories(path);
            foreach (string subdirectory in subdirectoryEntries)
                ScanDirectory(subdirectory, searchText);
        }
        catch (UnauthorizedAccessException ex)
        {
            Console.WriteLine($"Access denied to folder {path}: {ex.Message}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error scanning folder {path}: {ex.Message}");
        }
    }

    private static void ScanFile(string filePath, string searchText)
    {
        try
        {
            // This assumes that the file is not too large to fit into memory
            // For large files, you would need to read chunks of data and perform the search.
            string content = File.ReadAllText(filePath);
            if (content.Contains(searchText))
            {
                Console.WriteLine($"Text found in file: {filePath}");
            }
        }
        catch (FileNotFoundException)
        {
            // If file is deleted by a concurrent process
        }
        catch (UnauthorizedAccessException)
        {
            // If access to file is denied
        }
        catch (Exception ex)
        {
            // Could be an IOException, OutOfMemoryException, or any other exception thrown by File.ReadAllText
            Console.WriteLine($"Error reading file {filePath}: {ex.Message}");
        }
    }
}
