            self.connections.append(conn)

    def to_dict(self) -> dict:
        """Convert LAG to dict format."""
        return {
            "lagId": self.lag_id,
            "location": self.location,
            "connectionsBandwidth": self.connections_bandwidth,
            "lagName": self.lag_name,
            "lagState": self.lag_state,
            "macSecCapable": self.mac_sec_capable,
            "macSecKeys": self.mac_sec_keys,
            "encryptionMode": self.encryption_mode,
            "connections": [conn.to_dict() for conn in self.connections],
        }


class DirectConnectBackend(BaseBackend):
    """Implementation of DirectConnect APIs."""

    def __init__(self, region_name: str = None):
        """Initialize DirectConnect backend."""
        super().__init__()
        self.region_name = region_name
        self.connections: Dict[str, DirectConnectConnection] = {}
        self.lags: Dict[str, DirectConnectLag] = {}

    def create_connection(
        self,
        location: str,
        bandwidth: str,
        connection_name: str,
        request_mac_sec: bool = False,
    ) -> dict:
        """Create a new DirectConnect connection."""
        connection = DirectConnectConnection(
            location=location,
            bandwidth=bandwidth,
            connection_name=connection_name,
            request_mac_sec=request_mac_sec,
        )
        self.connections[connection.connection_id] = connection
        return connection.to_dict()

    def describe_connections(self, connection_id: Optional[str] = None) -> dict:
        """Describe one or all DirectConnect connections."""
        connections = []
        if connection_id:
            if connection_id in self.connections:
                connections = [self.connections[connection_id].to_dict()]
        else:
            connections = [conn.to_dict() for conn in self.connections.values()]
        return {"connections": connections}

    def delete_connection(self, connection_id: str) -> dict:
        """Delete a DirectConnect connection."""
        if connection_id in self.connections:
            connection = self.connections[connection_id]
            connection.connection_state = "deleted"
            del self.connections[connection_id]
            return connection.to_dict()
        return {}

    def update_connection(
        self, connection_id: str, connection_name: Optional[str] = None, encryption_mode: Optional[str] = None
    ) -> dict:
        """Update a DirectConnect connection."""
        if connection_id in self.connections:
            connection = self.connections[connection_id]
            if connection_name:
                connection.connection_name = connection_name
            if encryption_mode:
                connection.encryption_mode = encryption_mode
            return connection.to_dict()
        return {}

    def create_lag(
        self,
        number_of_connections: int,
        location: str,
        connections_bandwidth: str,
        lag_name: str,
        request_mac_sec: bool = False,
    ) -> dict:
        """Create a new DirectConnect LAG."""
        lag = DirectConnectLag(
            location=location,
            connections_bandwidth=connections_bandwidth,
            lag_name=lag_name,
            number_of_connections=number_of_connections,
            request_mac_sec=request_mac_sec,
        )
        self.lags[lag.lag_id] = lag
        # Add LAG connections to the connections dict
        for conn in lag.connections:
            self.connections[conn.connection_id] = conn
        return lag.to_dict()

    def describe_lags(self, lag_id: Optional[str] = None) -> dict:
        """Describe one or all DirectConnect LAGs."""
        lags = []
        if lag_id:
            if lag_id in self.lags:
                lags = [self.lags[lag_id].to_dict()]
        else:
            lags = [lag.to_dict() for lag in self.lags.values()]
        return {"lags": lags}

    def associate_mac_sec_key(
        self, connection_id: str, ckn: str, cak: str, secret_arn: str = "mock_secret_arn"
    ) -> dict:
        """Associate a MACsec key with a connection or LAG."""
        mac_sec_key = {
            "ckn": ckn,
            "secretARN": secret_arn,
            "state": "associated",
        }

        if connection_id in self.connections:
            connection = self.connections[connection_id]
            connection.mac_sec_keys = [mac_sec_key]
            return {
                "connectionId": connection_id,
                "macSecKeys": connection.mac_sec_keys,
            }
        elif connection_id in self.lags:
            lag = self.lags[connection_id]
            lag.mac_sec_keys = [mac_sec_key]
            # Also update all connections in the LAG
            for conn in lag.connections:
                conn.mac_sec_keys = [mac_sec_key.copy()]
            return {
                "connectionId": connection_id,
                "macSecKeys": lag.mac_sec_keys,
            }
        return {}

    def disassociate_mac_sec_key(self, connection_id: str, secret_arn: str) -> dict:
        """Disassociate a MACsec key from a connection or LAG."""
        if connection_id in self.connections:
            connection = self.connections[connection_id]
            for key in connection.mac_sec_keys:
                if key["secretARN"] == secret_arn:
                    key["state"] = "disassociated"
            return {
                "connectionId": connection_id,
                "macSecKeys": connection.mac_sec_keys,
            }
        elif connection_id in self.lags:
            lag = self.lags[connection_id]
            for key in lag.mac_sec_keys:
                if key["secretARN"] == secret_arn:
                    key["state"] = "disassociated"
            # Also update all connections in the LAG
            for conn in lag.connections:
                for key in conn.mac_sec_keys:
                    if key["secretARN"] == secret_arn:
                        key["state"] = "disassociated"
            return {
                "connectionId": connection_id,
                "macSecKeys": lag.mac_sec_keys,
