    """Given a set of items to be inserted, make sure they all have the
    same columns by padding columns with None if they are missing.

    If columns is not provided, it will be derived from all keys in all records.
    """
    if not chunk:
        return chunk

    # If columns not provided, derive them from all records in the chunk
    if columns is None:
        columns = set()
        for record in chunk:
